#include "OfflineRenderer.h"
namespace cymbalforge { bool OfflineRenderer::renderWav(const juce::File& file,CymbalParameters& p,double seconds) { constexpr double rate=48000; auto samples=int(rate*seconds); juce::AudioBuffer<float> b(2,samples); CymbalEngine e; e.parameters.velocity=p.velocity.load(); e.parameters.position=p.position.load(); e.parameters.brightness=p.brightness.load(); e.parameters.decay=p.decay.load(); e.parameters.complexity=p.complexity.load(); e.parameters.shimmer=p.shimmer.load(); e.parameters.noise=p.noise.load(); e.parameters.reverb=p.reverb.load(); e.parameters.gain=p.gain.load(); e.parameters.modes=p.modes.load(); e.prepare(rate,512); e.strike(e.parameters.velocity.load(),e.parameters.position.load()); for(int at=0;at<samples;at+=512) e.render(b,at,juce::jmin(512,samples-at)); file.deleteFile(); auto stream=std::unique_ptr<juce::FileOutputStream>(file.createOutputStream()); if(!stream) return false; juce::WavAudioFormat wav; auto writer=std::unique_ptr<juce::AudioFormatWriter>(wav.createWriterFor(stream.release(),rate,2,24,{},0)); return writer && writer->writeFromAudioSampleBuffer(b,0,samples); } }
